// Deterministic results. gen-reference.mjs runs this same function under
// Node and stores its answers in REFERENCE; the fixture runs it here and
// compares, so every expected value comes from Node's implementation.
export function compute(keys) {
  const out = {};
  for (const algorithm of ["md5", "sha1", "sha256", "sha384", "sha512"]) {
    out[`createHash ${algorithm}`] = crypto.createHash(algorithm).update("ab").update("c").digest("hex");
    out[`createHmac ${algorithm}`] = crypto.createHmac(algorithm, "key").update(message).digest("base64");
  }
  out["hash sha256"] = crypto.hash("sha256", message);
  out["pbkdf2Sync sha256"] = crypto.pbkdf2Sync("passwd", "salt", 1000, 64, "sha256").toString("hex");
  out["pbkdf2Sync sha512"] = crypto.pbkdf2Sync("passwd", "salt", 1000, 64, "sha512").toString("hex");
  out["hkdfSync sha256"] = Buffer.from(crypto.hkdfSync("sha256", "ikm", "salt", "info", 42)).toString("hex");
  for (const [name, args] of Object.entries(SCRYPT)) {
    // Node words a rejected N from whatever error OpenSSL still has queued, so
    // after a memory-limit failure a bad N reports that one too. A successful
    // derivation empties the queue, and each case starts from an empty one.
    crypto.scryptSync("", "", 1, { N: 2, r: 1, p: 1 });
    try {
      out[`scryptSync ${name}`] = crypto.scryptSync(...args).toString("hex");
    } catch (error) {
      out[`scryptSync ${name}`] = `${error.constructor.name} ${error.code}: ${error.message}`;
    }
  }
  // Arguments that must fit an unsigned 32-bit integer share one validator
  // with scrypt's N, r and p.
  for (const [name, call] of Object.entries({
    "hash outputLength 2^32": () => crypto.createHash("shake128", { outputLength: 2 ** 32 }),
    "rsa modulusLength 2^32": () => crypto.generateKeyPairSync("rsa", { modulusLength: 2 ** 32 }),
    "rsa publicExponent -1": () => crypto.generateKeyPairSync("rsa", { modulusLength: 1024, publicExponent: -1 }),
  })) {
    try {
      call();
      out[`range ${name}`] = "no error";
    } catch (error) {
      out[`range ${name}`] = `${error.constructor.name} ${error.code}: ${error.message}`;
    }
  }
  // PKCS#1 v1.5 and Ed25519 signatures are deterministic.
  out["sign RSA-SHA256"] = crypto.sign("sha256", message, keys.rsa.private).toString("base64");
  out["sign RSA-SHA512"] = crypto.sign("sha512", message, keys.rsa.private).toString("base64");
  out["sign Ed25519"] = crypto.sign(null, message, keys.ed25519.private).toString("base64");
  for (const [name, pair] of Object.entries(keys)) {
    const priv = crypto.createPrivateKey(pair.private);
    const pub = crypto.createPublicKey(pair.private);
    out[`createPublicKey ${name}`] = pub.export({ type: "spki", format: "pem" });
    // Member order carries no meaning in a JWK, so it is compared sorted.
    const jwk = pub.export({ format: "jwk" });
    out[`export jwk ${name}`] = JSON.stringify(jwk, Object.keys(jwk).sort());
    out[`asymmetricKeyType ${name}`] = `${priv.asymmetricKeyType}/${pub.asymmetricKeyType}`;
  }
  // Every EC key exports as SEC1 and comes back from it, and a typed private
  // PEM yields its public half.
  for (const curve of ["p256", "p384", "p521"]) {
    const priv = crypto.createPrivateKey(keys[curve].private);
    const sec1 = priv.export({ type: "sec1", format: "der" });
    out[`export sec1 ${curve}`] = sec1.toString("base64");
    out[`import sec1 ${curve}`] = crypto
      .createPrivateKey({ key: sec1, format: "der", type: "sec1" })
      .export({ type: "pkcs8", format: "pem" });
    for (const type of ["pkcs8", "sec1"]) {
      const pem = priv.export({ type, format: "pem" });
      out[`createPublicKey ${curve} from ${type}`] = crypto
        .createPublicKey({ key: pem, format: "pem", type })
        .export({ type: "spki", format: "pem" });
    }
  }
  out["createSecretKey"] = crypto.createSecretKey(Buffer.from("0123456789abcdef")).export().toString("hex");
  return out;
}

function equal(actual, expected, what) {
  if (actual !== expected) throw new Error(`${what}: got ${actual}, want ${expected}`);
}

// Signature round trips for every key type, including randomized ECDSA:
// the reference signature verifies, a tampered message does not, and a
// signature made here verifies.
function roundTrip(name, hash, pair, reference) {
  const pub = crypto.createPublicKey(pair.private);
  if (reference) {
    equal(crypto.verify(hash, message, pub, Buffer.from(reference, "base64")), true, `${name}: reference verifies`);
  }
  const own = crypto.sign(hash, message, pair.private);
  equal(crypto.verify(hash, message, pub, own), true, `${name}: own signature verifies`);
  equal(crypto.verify(hash, tampered, pub, own), false, `${name}: tampered verifies`);
}

const checks = {
  reference() {
    const actual = compute(KEYS);
    const failed = Object.keys(REFERENCE).filter((key) => actual[key] !== REFERENCE[key]);
    if (failed.length) throw new Error(`differs from Node: ${failed.join(", ")}`);
    equal(Object.keys(actual).length, Object.keys(REFERENCE).length, "result count");
  },
  "sign and verify"() {
    roundTrip("RSA", "sha256", KEYS.rsa, REFERENCE["sign RSA-SHA256"]);
    roundTrip("Ed25519", null, KEYS.ed25519, REFERENCE["sign Ed25519"]);
    for (const curve of ["p256", "p384", "p521"]) {
      for (const hash of ["sha256", "sha384", "sha512"]) {
        roundTrip(`ECDSA ${curve} ${hash}`, hash, KEYS[curve], ECDSA[`${curve} ${hash}`]);
      }
    }
  },
  // `padding`, `saltLength` and `dsaEncoding` change the signature a key
  // makes, so each is honoured: a PSS request must never come back as a
  // PKCS#1 v1.5 signature.
  "sign and verify options"() {
    const { RSA_PKCS1_PSS_PADDING: PSS_PADDING, RSA_NO_PADDING } = crypto.constants;
    const pub = crypto.createPublicKey(KEYS.rsa.private);
    const pss = (saltLength) => ({ padding: PSS_PADDING, saltLength });
    const verifyPss = (signature, saltLength, data = message) =>
      crypto.verify("sha256", data, { key: pub, ...pss(saltLength) }, signature);
    // Node's PSS signatures verify with the salt length they were made with,
    // and with the default of reading it off the signature.
    for (const [name, saltLength] of [["max", -2], ["digest", -1], ["20", 20]]) {
      const reference = Buffer.from(PSS[name], "base64");
      equal(verifyPss(reference, saltLength), true, `reference PSS ${name}`);
      equal(crypto.verify("sha256", message, { key: pub, padding: PSS_PADDING }, reference), true, `reference PSS ${name} with the salt read off`);
      equal(crypto.verify("sha256", message, pub, reference), false, `reference PSS ${name} read as PKCS#1 v1.5`);
    }
    equal(verifyPss(Buffer.from(PSS["20"], "base64"), -1), false, "salt 20 against the digest length");
    // The signature made here is PSS, at the salt length asked for.
    const own = crypto.sign("sha256", message, { key: KEYS.rsa.private, padding: PSS_PADDING });
    equal(own.length, 256, "PSS signature length");
    equal(verifyPss(own, -2), true, "own PSS verifies");
    equal(verifyPss(own, 222), true, "own PSS defaults to the largest salt for a 2048-bit key");
    equal(verifyPss(own, -1), false, "own PSS is not at the digest length");
    equal(verifyPss(own, -2, tampered), false, "tampered PSS verifies");
    equal(crypto.verify("sha256", message, pub, own), false, "own PSS read as PKCS#1 v1.5");
    const digest = crypto.sign("sha256", message, { key: KEYS.rsa.private, ...pss(-1) });
    equal(verifyPss(digest, 32), true, "own PSS at the digest length");
    equal(crypto.verify("sha256", message, pub, crypto.sign("sha256", message, { key: KEYS.rsa.private, padding: crypto.constants.RSA_PKCS1_PADDING })), true, "explicit PKCS#1 v1.5");
    // A padding that is not implemented throws instead of signing another way.
    for (const call of [
      () => crypto.sign("sha256", message, { key: KEYS.rsa.private, padding: RSA_NO_PADDING }),
      () => crypto.verify("sha256", message, { key: pub, padding: RSA_NO_PADDING }, own),
    ]) {
      let threw = false;
      try { call(); } catch { threw = true; }
      equal(threw, true, "an unsupported RSA padding throws");
    }
    // `saltLength` means nothing without PSS padding, so it is ignored there.
    const plain = crypto.sign("sha256", message, KEYS.rsa.private);
    equal(crypto.sign("sha256", message, { key: KEYS.rsa.private, saltLength: 20 }).equals(plain), true, "saltLength without PSS padding");
    equal(crypto.verify("sha256", message, { key: pub, saltLength: 20 }, plain), true, "verify with saltLength and no PSS padding");
    // A salt the modulus cannot hold throws; 222 is the most a 2048-bit key
    // holds with SHA-256.
    equal(crypto.verify("sha256", message, { key: pub, ...pss(222) }, crypto.sign("sha256", message, { key: KEYS.rsa.private, ...pss(222) })), true, "the largest salt");
    for (const saltLength of [223, 1000, 2 ** 31 - 1]) {
      let threw = false;
      try { crypto.sign("sha256", message, { key: KEYS.rsa.private, ...pss(saltLength) }); } catch { threw = true; }
      equal(threw, true, `PSS saltLength ${saltLength} throws`);
    }
    // ECDSA signatures are DER unless IEEE P1363 is asked for.
    for (const [curve, size] of [["p256", 32], ["p384", 48], ["p521", 66]]) {
      const key = crypto.createPublicKey(KEYS[curve].private);
      const reference = Buffer.from(P1363[curve], "base64");
      equal(reference.length, 2 * size, `${curve} P1363 reference length`);
      equal(crypto.verify("sha256", message, { key, dsaEncoding: "ieee-p1363" }, reference), true, `${curve} P1363 reference verifies`);
      equal(crypto.verify("sha256", message, key, reference), false, `${curve} P1363 reference read as DER`);
      const raw = crypto.sign("sha256", message, { key: KEYS[curve].private, dsaEncoding: "ieee-p1363" });
      equal(raw.length, 2 * size, `${curve} own P1363 length`);
      equal(crypto.verify("sha256", message, { key, dsaEncoding: "ieee-p1363" }, raw), true, `${curve} own P1363 verifies`);
      equal(crypto.verify("sha256", tampered, { key, dsaEncoding: "ieee-p1363" }, raw), false, `${curve} own P1363 tampered`);
      const der = crypto.sign("sha256", message, { key: KEYS[curve].private, dsaEncoding: "der" });
      equal(crypto.verify("sha256", message, key, der), true, `${curve} explicit DER verifies`);
      let code;
      try { crypto.sign("sha256", message, { key: KEYS[curve].private, dsaEncoding: "x" }); } catch (error) { code = error.code; }
      equal(code, "ERR_INVALID_ARG_VALUE", `${curve} unknown dsaEncoding`);
    }
  },
  generateKeyPairSync() {
    // Each case names the key details Node reports for what was asked for,
    // so a generator that ignores the curve or the length fails here.
    const cases = [
      ["rsa", { modulusLength: 1024 }, "sha256", { modulusLength: 1024, publicExponent: 65537n }],
      ["ec", { namedCurve: "P-256" }, "sha256", { namedCurve: "prime256v1" }],
      ["ec", { namedCurve: "secp384r1" }, "sha384", { namedCurve: "secp384r1" }],
      ["ec", { namedCurve: "P-521" }, "sha512", { namedCurve: "secp521r1" }],
      ["ed25519", {}, null, {}],
    ];
    for (const [type, options, hash, details] of cases) {
      const a = crypto.generateKeyPairSync(type, options);
      equal(a.publicKey.asymmetricKeyType, type, `${type}: key type`);
      for (const [field, value] of Object.entries(details)) {
        equal(a.publicKey.asymmetricKeyDetails[field], value, `${type} ${JSON.stringify(options)}: ${field}`);
      }
      const b = crypto.generateKeyPairSync(type, options);
      const spki = (pair) => pair.publicKey.export({ type: "spki", format: "der" }).toString("hex");
      equal(spki(a) === spki(b), false, `${type}: two generated pairs are equal`);
      const sig = crypto.sign(hash, message, a.privateKey);
      equal(crypto.verify(hash, message, a.publicKey, sig), true, `${type}: verifies`);
      if (type === "ec") {
        const sec1 = a.privateKey.export({ type: "sec1", format: "pem" });
        const back = crypto.createPrivateKey(sec1);
        equal(back.asymmetricKeyDetails.namedCurve, details.namedCurve, `${options.namedCurve}: curve after a SEC1 round trip`);
      }
      const pem = a.privateKey.export({ type: "pkcs8", format: "pem" });
      const again = crypto.sign(hash, message, crypto.createPrivateKey(pem));
      equal(crypto.verify(hash, message, a.publicKey, again), true, `${type}: verifies after a PEM round trip`);
    }
  },
  "private key round trips"() {
    const pem = KEYS.rsa.private;
    const rsa = crypto.createPrivateKey(pem);
    const jwk = rsa.export({ format: "jwk" });
    equal(crypto.createPrivateKey({ key: jwk, format: "jwk" }).export({ type: "pkcs8", format: "pem" }), pem, "RSA private JWK");
    for (const cipher of ["aes-128-cbc", "aes-256-cbc"]) {
      const sealed = rsa.export({ type: "pkcs8", format: "pem", cipher, passphrase: "secret" });
      equal(crypto.createPrivateKey({ key: sealed, passphrase: "secret" }).export({ type: "pkcs8", format: "pem" }), pem, `encrypted PKCS#8 ${cipher}`);
    }
    const dsa = crypto.createPrivateKey(DSA_TRADITIONAL);
    equal(dsa.export({ type: "pkcs8", format: "pem" }), DSA_PKCS8, "traditional DSA as PKCS#8");
    equal(`${dsa.asymmetricKeyDetails.modulusLength}/${dsa.asymmetricKeyDetails.divisorLength}`, "2048/224", "traditional DSA sizes");
  },
  "random and comparison"() {
    equal(crypto.randomBytes(32).length, 32, "randomBytes length");
    equal(crypto.randomBytes(16).equals(crypto.randomBytes(16)), false, "two random draws are equal");
    equal(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(crypto.randomUUID()), true, "randomUUID format");
    equal(crypto.timingSafeEqual(Buffer.from("same"), Buffer.from("same")), true, "equal buffers");
    equal(crypto.timingSafeEqual(Buffer.from("same"), Buffer.from("diff")), false, "different buffers");
  },
  async callbacks() {
    const derived = await new Promise((resolve, reject) =>
      crypto.pbkdf2("passwd", "salt", 1000, 64, "sha256", (error, key) => (error ? reject(error) : resolve(key))),
    );
    equal(derived.toString("hex"), REFERENCE["pbkdf2Sync sha256"], "pbkdf2 callback");
  },
  async scrypt() {
    const callback = (...args) =>
      new Promise((resolve, reject) =>
        crypto.scrypt(...args, (error, key) => (error ? reject(error) : resolve(key))),
      );
    // Every case that derived a key does the same through the callback form,
    // with and without the options argument.
    for (const [name, args] of Object.entries(SCRYPT)) {
      const expected = REFERENCE[`scryptSync ${name}`];
      if (!/^[0-9a-f]*$/.test(expected)) continue;
      const key = await callback(...args);
      equal(Buffer.isBuffer(key), true, `${name}: callback key is a Buffer`);
      equal(key.toString("hex"), expected, `${name}: callback key`);
    }
    equal((await callback(pw, salt, 32)).toString("hex"), REFERENCE["scryptSync default parameters"], "callback without options");
    // Node checks the parameters before it queues the job, so a bad one
    // throws from scrypt() itself and the callback never runs.
    for (const [name, args] of Object.entries(SCRYPT)) {
      const expected = REFERENCE[`scryptSync ${name}`];
      if (/^[0-9a-f]*$/.test(expected)) continue;
      let called = false;
      let message;
      try {
        crypto.scrypt(...args, () => { called = true; });
      } catch (error) {
        message = `${error.constructor.name} ${error.code}: ${error.message}`;
      }
      equal(message, expected, `${name}: scrypt throws as scryptSync does`);
      equal(called, false, `${name}: callback is not called`);
    }
    for (const bad of [undefined, "x", null]) {
      let code;
      try { crypto.scrypt(pw, salt, 16, { N: 16 }, bad); } catch (error) { code = error.code; }
      equal(code, "ERR_INVALID_ARG_TYPE", `callback ${String(bad)}`);
    }
    equal(crypto.scrypt(pw, salt, 16, () => {}), undefined, "scrypt returns undefined");
  },
};

export default {
  async fetch(request) {
    if (new URL(request.url).pathname === "/__ready") return new Response("ready");
    const results = {};
    for (const [name, check] of Object.entries(checks)) {
      try {
        await check();
        results[name] = "ok";
      } catch (error) {
        results[name] = `fail: ${error?.message ?? error}`;
      }
    }
    return Response.json(results);
  },
};
